SELECT 'part_cpu' AS tbl, COUNT(*) AS n, ROUND(100*SUM(socket IS NULL)/COUNT(*)) AS socket,ROUND(100*SUM(microarchitecture IS NULL)/COUNT(*)) AS microarchitecture,ROUND(100*SUM(core_family IS NULL)/COUNT(*)) AS core_family,ROUND(100*SUM(cores_total IS NULL)/COUNT(*)) AS cores_total,ROUND(100*SUM(threads IS NULL)/COUNT(*)) AS threads,ROUND(100*SUM(base_clock IS NULL)/COUNT(*)) AS base_clock,ROUND(100*SUM(boost_clock IS NULL)/COUNT(*)) AS boost_clock,ROUND(100*SUM(tdp IS NULL)/COUNT(*)) AS tdp,ROUND(100*SUM(integrated_graphics IS NULL)/COUNT(*)) AS integrated_graphics,ROUND(100*SUM(release_year IS NULL)/COUNT(*)) AS release_year,ROUND(100*SUM(price_cny IS NULL)/COUNT(*)) AS price_cny,ROUND(100*SUM(price_usd IS NULL)/COUNT(*)) AS price_usd FROM part_cpu;
SELECT 'part_cpu_cooler' AS tbl, COUNT(*) AS n, ROUND(100*SUM(water_cooled IS NULL)/COUNT(*)) AS water_cooled,ROUND(100*SUM(radiator_size IS NULL)/COUNT(*)) AS radiator_size,ROUND(100*SUM(fan_size IS NULL)/COUNT(*)) AS fan_size,ROUND(100*SUM(fan_quantity IS NULL)/COUNT(*)) AS fan_quantity,ROUND(100*SUM(min_fan_rpm IS NULL)/COUNT(*)) AS min_fan_rpm,ROUND(100*SUM(max_fan_rpm IS NULL)/COUNT(*)) AS max_fan_rpm,ROUND(100*SUM(min_noise IS NULL)/COUNT(*)) AS min_noise,ROUND(100*SUM(max_noise IS NULL)/COUNT(*)) AS max_noise,ROUND(100*SUM(height IS NULL)/COUNT(*)) AS height,ROUND(100*SUM(cpu_sockets IS NULL)/COUNT(*)) AS cpu_sockets,ROUND(100*SUM(release_year IS NULL)/COUNT(*)) AS release_year,ROUND(100*SUM(price_cny IS NULL)/COUNT(*)) AS price_cny FROM part_cpu_cooler;
SELECT 'part_gpu' AS tbl, COUNT(*) AS n, ROUND(100*SUM(chipset IS NULL)/COUNT(*)) AS chipset,ROUND(100*SUM(chipset_manufacturer IS NULL)/COUNT(*)) AS chipset_manufacturer,ROUND(100*SUM(core_base_clock IS NULL)/COUNT(*)) AS core_base_clock,ROUND(100*SUM(memory_gb IS NULL)/COUNT(*)) AS memory_gb,ROUND(100*SUM(memory_type IS NULL)/COUNT(*)) AS memory_type,ROUND(100*SUM(effective_memory_clock IS NULL)/COUNT(*)) AS effective_memory_clock,ROUND(100*SUM(tdp IS NULL)/COUNT(*)) AS tdp,ROUND(100*SUM(gpu_interface IS NULL)/COUNT(*)) AS gpu_interface,ROUND(100*SUM(length_mm IS NULL)/COUNT(*)) AS length_mm,ROUND(100*SUM(slot_width IS NULL)/COUNT(*)) AS slot_width,ROUND(100*SUM(cooling IS NULL)/COUNT(*)) AS cooling,ROUND(100*SUM(frame_sync IS NULL)/COUNT(*)) AS frame_sync,ROUND(100*SUM(release_year IS NULL)/COUNT(*)) AS release_year,ROUND(100*SUM(price_cny IS NULL)/COUNT(*)) AS price_cny FROM part_gpu;
SELECT 'part_motherboard' AS tbl, COUNT(*) AS n, ROUND(100*SUM(socket IS NULL)/COUNT(*)) AS socket,ROUND(100*SUM(chipset IS NULL)/COUNT(*)) AS chipset,ROUND(100*SUM(form_factor IS NULL)/COUNT(*)) AS form_factor,ROUND(100*SUM(memory_max IS NULL)/COUNT(*)) AS memory_max,ROUND(100*SUM(memory_type IS NULL)/COUNT(*)) AS memory_type,ROUND(100*SUM(memory_slots IS NULL)/COUNT(*)) AS memory_slots,ROUND(100*SUM(wireless IS NULL)/COUNT(*)) AS wireless,ROUND(100*SUM(release_year IS NULL)/COUNT(*)) AS release_year,ROUND(100*SUM(price_cny IS NULL)/COUNT(*)) AS price_cny FROM part_motherboard;
SELECT 'part_pc_case' AS tbl, COUNT(*) AS n, ROUND(100*SUM(form_factor IS NULL)/COUNT(*)) AS form_factor,ROUND(100*SUM(color IS NULL)/COUNT(*)) AS color,ROUND(100*SUM(side_panel IS NULL)/COUNT(*)) AS side_panel,ROUND(100*SUM(power_supply IS NULL)/COUNT(*)) AS power_supply,ROUND(100*SUM(max_gpu_length IS NULL)/COUNT(*)) AS max_gpu_length,ROUND(100*SUM(max_cooler_height IS NULL)/COUNT(*)) AS max_cooler_height,ROUND(100*SUM(volume_l IS NULL)/COUNT(*)) AS volume_l,ROUND(100*SUM(weight_kg IS NULL)/COUNT(*)) AS weight_kg,ROUND(100*SUM(release_year IS NULL)/COUNT(*)) AS release_year,ROUND(100*SUM(price_cny IS NULL)/COUNT(*)) AS price_cny FROM part_pc_case;
SELECT 'part_psu' AS tbl, COUNT(*) AS n, ROUND(100*SUM(wattage IS NULL)/COUNT(*)) AS wattage,ROUND(100*SUM(form_factor IS NULL)/COUNT(*)) AS form_factor,ROUND(100*SUM(efficiency IS NULL)/COUNT(*)) AS efficiency,ROUND(100*SUM(modular IS NULL)/COUNT(*)) AS modular,ROUND(100*SUM(length_mm IS NULL)/COUNT(*)) AS length_mm,ROUND(100*SUM(release_year IS NULL)/COUNT(*)) AS release_year,ROUND(100*SUM(price_cny IS NULL)/COUNT(*)) AS price_cny FROM part_psu;
SELECT 'part_ram' AS tbl, COUNT(*) AS n, ROUND(100*SUM(ram_type IS NULL)/COUNT(*)) AS ram_type,ROUND(100*SUM(speed_mt IS NULL)/COUNT(*)) AS speed_mt,ROUND(100*SUM(capacity_gb IS NULL)/COUNT(*)) AS capacity_gb,ROUND(100*SUM(modules_qty IS NULL)/COUNT(*)) AS modules_qty,ROUND(100*SUM(module_gb IS NULL)/COUNT(*)) AS module_gb,ROUND(100*SUM(form_factor IS NULL)/COUNT(*)) AS form_factor,ROUND(100*SUM(cas_latency IS NULL)/COUNT(*)) AS cas_latency,ROUND(100*SUM(voltage IS NULL)/COUNT(*)) AS voltage,ROUND(100*SUM(release_year IS NULL)/COUNT(*)) AS release_year,ROUND(100*SUM(price_cny IS NULL)/COUNT(*)) AS price_cny FROM part_ram;
SELECT 'part_storage' AS tbl, COUNT(*) AS n, ROUND(100*SUM(storage_type IS NULL)/COUNT(*)) AS storage_type,ROUND(100*SUM(capacity_gb IS NULL)/COUNT(*)) AS capacity_gb,ROUND(100*SUM(form_factor IS NULL)/COUNT(*)) AS form_factor,ROUND(100*SUM(hard_interface IS NULL)/COUNT(*)) AS hard_interface,ROUND(100*SUM(nvme IS NULL)/COUNT(*)) AS nvme,ROUND(100*SUM(cache_mb IS NULL)/COUNT(*)) AS cache_mb,ROUND(100*SUM(release_year IS NULL)/COUNT(*)) AS release_year,ROUND(100*SUM(price_cny IS NULL)/COUNT(*)) AS price_cny FROM part_storage;